using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.Laman;

internal sealed class PlanarRowsDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/Laman/PlanarRows.";
    private static readonly LibraryNoteRef Source =
        LibraryNoteRef.Create("D5/L/Geometry/chen2026combinatorialrigidity");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Independent rows, perturbations along a moment curve, and all induced-subset sparsity bounds.",
        H("PlanarRows"), Blocks(
            Describe.Lean(DescribeId.Create("planarrows-0"),
                DeclarationHandle.Create(Prefix + "range_dualMap_eq_span_image_dualBasis"),
                H("The row space as a span"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For a commutative semiring, real or otherwise, modules M,N, a basis b of N with a finite decidable index type, and a linear map f from M to N, the range of the dual map is the span of f.dualMap applied to the dual basis."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-1"),
                DeclarationHandle.Create(Prefix + "eval_det_X_add_C"),
                H("Evaluating the determinant polynomial"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For any commutative ring, finite decidable matrix index type, square matrices A,B and scalar t, evaluating det(X times A.map(C)+B.map(C)) at t gives det(t times A+B)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-2"),
                DeclarationHandle.Create(Prefix + "det_powerDifferences"),
                H("The moment-curve difference determinant"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For every commutative ring, natural n and vector v indexed by Fin(n+1), the determinant of the n by n matrix with entry v(i+1)^(j+1)-v(0)^(j+1) equals the product of v(j)-v(i) over all i<j. A cofactor expansion of the Vandermonde evaluation matrix gives the identity, including n=0."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-3"),
                DeclarationHandle.Create(Prefix + "EdgeSetRowIndependent"),
                H("Row independence"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For every V,d,G,p and set I of actual edges of G, row independence means linear independence of the real-valued velocity functionals indexed by I."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("planarrows-4"),
                DeclarationHandle.Create(Prefix + "rigidityRow"),
                H("Rows as dual vectors"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For every graph and placement, rigidityRow p e is the real linear functional obtained by composing the rigidity map with the coordinate projection at the actual edge e."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("planarrows-5"),
                DeclarationHandle.Create(Prefix + "edgeSetRowIndependent_iff_linearIndepOn_rigidityRow"),
                H("The function and dual formulations agree"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For every graph, placement and set of actual edges, linear independence of their velocity functions is equivalent to linear independence of the corresponding dual vectors."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-6"),
                DeclarationHandle.Create(Prefix + "rigidityRow_lift_eq_funLeft_dualMap"),
                H("Factoring a lifted edge row"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For any map phi from V to W, graphs Gprime,H, compatible placements pprime,pext with pext(phi(v))=pprime(v), and an actual Gprime edge whose mapped unordered pair is an H edge, the H row equals the Gprime row pulled back through restriction of velocities along phi. Injectivity of phi is not a premise."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-7"),
                DeclarationHandle.Create(Prefix + "linearIndependent_rigidityRow_of_lift"),
                H("Pulling independence back to an induced graph"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For any phi, compatible placements, arbitrary indexing family of Gprime edges and proofs that their lifts are H edges, linear independence of the lifted H rows implies linear independence of the original Gprime rows. Factoring through the dual of velocity restriction proves the implication."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-8"),
                DeclarationHandle.Create(Prefix + "span_range_rigidityRow"),
                H("Row span and transpose range"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For any graph with finitely many edges and any real placement, the span of all rigidity rows equals the range of the rigidity map dual."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-9"),
                DeclarationHandle.Create(Prefix + "rigidityMap_finrank_range_le_of_affinelySpanning"),
                H("Rank upper bound"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For every finite enumeration of V and placement p affinely spanning the real d-dimensional Euclidean space, rank(RigidityMap)+d(d+1)/2<=d card(V). The trivial-motion kernel lower bound and rank-nullity give the inequality."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-10"),
                DeclarationHandle.Create(Prefix + "exists_edgeSetRowIndependent_of_finrank_range_ge_dim_two"),
                H("Selecting an independent edge set"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For every finite enumeration of V, graph G and planar placement p with 2 card(V)<=rank(RigidityMap)+3, there is a set I of actual G edges of cardinality 2 card(V)-3 whose rows at p are independent. Extend an independent subset to a spanning row family, identify its cardinality with the row rank, and take a subset of the required size."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-11"),
                DeclarationHandle.Create(Prefix + "exists_affinelySpanning_of_eventually"),
                H("Affine spanning while preserving an open property"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For every finite V, dimension d, placement pzero and property P holding throughout some neighborhood of pzero, there exists p satisfying P such that its restriction to every vertex set S with card(S)>=d+1 affinely spans the whole Euclidean space. Assign distinct real parameters to the vertices and perturb along the moment curve. For each injective (d+1)-tuple, a determinant polynomial has nonzero top coefficient, so only finitely many perturbation values fail. A finite union of those exceptional sets leaves a value in the required neighborhood."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("planarrows-12"),
                DeclarationHandle.Create(Prefix + "isSparse_of_edgeSetRowIndependent_dim_two"),
                H("Every induced planar sparsity bound"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromLiterature(Source),
                Blocks(Paragraph(Text("For any vertex type, graph G, planar placement p affinely spanning on every vertex subset of cardinality at least three, and row-independent set I of actual G edges, the graph fromEdgeSet(image val I) is (2,3)-sparse. For a two-vertex subset, simplicity gives at most one edge. For every larger finite subset, factor the lifted rows through velocity restriction, retain independence, and combine their number with the restricted rigidity rank upper bound. The conclusion quantifies over every eligible finite subset."))), DescribeRole.Theorem)), []));
}
